const $=s=>document.querySelector(s),symbols={F:'↑',L:'↶',R:'↷'},labels={F:'Avanzar',L:'Izquierda',R:'Derecha'},directions=['↑','→','↓','←'];
let saved={};try{saved=JSON.parse(localStorage.getItem('semilla-v2')||'{}')||{}}catch{}if(typeof saved!=='object'||Array.isArray(saved))saved={};
let current=0,program=[],pos=[],direction=0,running=false,timer=null,voice=false,attempts=0,lastSuccess=false,mode='guided',tab='plan',errorIndex=-1;
const robot=()=>'<div class="robot" aria-label="Semilla, un robot con antena de flor"><div class="antenna">✿</div><div class="head"><div class="eyes"><i></i><i></i></div></div><div class="body">✿</div><div class="feet"></div></div>';
function say(text){if(voice&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='es-CO';u.rate=.85;speechSynthesis.speak(u)}}
function readConcept(){
 const status=$('#speech-status');
 if(!('speechSynthesis'in window)){if(status)status.textContent='La voz no está disponible en este navegador. Puedes leer los dos idiomas aquí.';return}
 const concept=MISSIONS[current].concept;
 speechSynthesis.cancel();
 const parts=[{lang:'en-US',text:'You won! Did you know? '+concept.en.title+'. '+concept.en.definition+' '+concept.en.example},{lang:'es-CO',text:'¡Ganaste! ¿Sabías que? '+concept.title+'. '+concept.definition+' '+concept.example}];
 const utterances=parts.map(part=>{const u=new SpeechSynthesisUtterance(part.text);u.lang=part.lang;u.rate=.8;const available=speechSynthesis.getVoices();const match=available.find(v=>v.lang.toLowerCase()===part.lang.toLowerCase())||available.find(v=>v.lang.split('-')[0]===part.lang.split('-')[0]);if(match)u.voice=match;u.onstart=()=>{if(status)status.textContent=part.lang==='en-US'?'Leyendo en inglés…':'Leyendo en español…'};u.onerror=e=>{if(status&&!['canceled','interrupted'].includes(e.error))status.textContent='No se pudo reproducir la voz. Comprueba las voces y el sonido del dispositivo.'};return u});
 utterances[1].onend=()=>{if(status)status.textContent='Lectura terminada. Puedes volver a escucharla.'};
 if(status)status.textContent='Preparando lectura: inglés y después español…';
 utterances.forEach(u=>speechSynthesis.speak(u));
}
function persist(){try{localStorage.setItem('semilla-v2',JSON.stringify(saved))}catch{}}
function stop(){clearTimeout(timer);running=false;if('speechSynthesis'in window)speechSynthesis.cancel()}
function route(){stop();document.querySelector('.overlay')?.remove();const hash=location.hash; if(/^#jugar-[1-6]$/.test(hash)){current=Number(hash.slice(-1))-1;program=[...(MISSIONS[current].initial||[])];attempts=0;lastSuccess=false;pos=[...MISSIONS[current].start];direction=0;errorIndex=-1;renderGame()}else if(hash==='#profes'){renderTeacher()}else renderHome();window.scrollTo(0,0)}
function updateBrandClock(){const now=new Date();document.querySelectorAll('[data-brand-time]').forEach(el=>el.textContent=new Intl.DateTimeFormat('es-CO',{timeZone:'America/Bogota',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(now));document.querySelectorAll('[data-brand-date]').forEach(el=>el.textContent=new Intl.DateTimeFormat('es-CO',{timeZone:'America/Bogota',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now));for(const part of ['day','month','year'])document.querySelectorAll('[data-brand-'+part+']').forEach(el=>el.textContent=new Intl.DateTimeFormat('es-CO',{timeZone:'America/Bogota',[part]:part==='month'?'long':'numeric'}).format(now))}
setInterval(updateBrandClock,1000);
function brandWidget(){return `<aside class="brand-widget" aria-label="TIME Codeman y reloj de Colombia"><div class="codeman-profile"><img src="data:image/png;base64," alt="Personaje de TIME Codeman" width="1024" height="1024" loading="lazy"><h3>TIME_CODEMAN</h3><p>Aprender, crear y compartir<br>conocimiento a otro nivel.</p><span class="profile-tag">Código con propósito</span></div><section class="neon-clock" aria-label="Hora actual de Colombia"><div class="clock-heading"><span class="clock-icon" aria-hidden="true">&lt;/&gt;</span><div><h3>Code Time</h3><p>Ideas · Código · Aprendizaje</p></div></div><div class="clock-digits" data-brand-time>--:--:--</div><p class="clock-date" data-brand-date>Hora de Colombia</p><div class="clock-message"><span aria-hidden="true">●</span> Modo aprender activado 🌱</div><div class="clock-calendar"><div><small>Día</small><strong data-brand-day>—</strong></div><div><small>Mes</small><strong data-brand-month>—</strong></div><div><small>Año</small><strong data-brand-year>—</strong></div></div><p class="clock-zone">Colombia · UTC−5</p></section></aside>`}
function authorCredit(){return `<section class="author-credit" aria-label="Autoría de Robot Semilla"><img class="author-banner" src="data:image/png;base64," alt="TIME Codeman: Código con propósito. Programación, Proyectos, TIME. @timecodeman" loading="lazy" width="2560" height="1440"><div class="author-caption"><img src="data:image/png;base64," alt="Personaje CodeMan 10.0" loading="lazy" width="1024" height="1024"><div><span class="eyebrow">Una creación de</span><h2>TIME Codeman</h2><p>Código con propósito · @timecodeman</p><small>Transforma · Innova · Motiva · Educa</small></div></div></section>`}
function renderHome(){const count=MISSIONS.filter((_,i)=>saved[i]?.complete).length;$('#app').innerHTML=`<section class="hero"><div><span class="eyebrow">Pequeños pasos. Grandes ideas.</span><h1 class="hero-title" data-bilingual-ready><span lang="es">Tu próxima aventura <em>crece contigo.</em></span><span class="hero-title-en" lang="en">Your next adventure grows with you.</span></h1><p>Ayuda a Semilla a cuidar su huerta. ¡Elige tus bloques y descubre hasta dónde puedes llegar!</p><a class="primary" href="#jugar-${Math.max(1,MISSIONS.findIndex((_,i)=>!saved[i]?.complete)+1)}">${count?'Seguir jugando':'¡Vamos a jugar!'} <span>▶</span></a><div><span class="pill">✦ 5–10 años</span><span class="pill">♡ Sin prisa</span><span class="pill">✓ Sin cuentas</span></div></div><div class="scene"><div class="sun"></div><span class="cloud">☁</span>${robot()}<div class="bubble">¡Hola! ¿Cultivamos ideas?</div><div class="sprouts"><span>🌷</span><span>🌱</span><span>🌻</span></div></div></section><section class="garden"><div><span class="eyebrow">Tu pequeño gran mundo</span><h2>Una huerta de logros</h2><p>${count} de 6 plantas cuidadas. Cada misión hace crecer una idea.</p></div><div class="plants" aria-label="${count} misiones completadas">${MISSIONS.map((m,i)=>`<span class="${saved[i]?.complete?'':'empty'}" title="${saved[i]?.complete?'Completada':'Por explorar'}">${m.plant}</span>`).join('')}</div></section><section><div class="section-title"><div><span class="eyebrow">Elige tu aventura</span><h2>Un bloque, un descubrimiento.</h2></div></div><div class="missions">${MISSIONS.map((m,i)=>`<a class="mission" href="#jugar-${i+1}"><div class="art ${m.color}">${m.plant}</div><small>MISIÓN 0${i+1} · ${m.skill.toUpperCase()}</small><h3>${m.title}</h3><p>${m.story}</p><span class="status">${saved[i]?.complete?'✓ Completada · Volver a jugar':'Explorar misión →'}</span></a>`).join('')}</div></section><section class="community-section"><div class="community-copy"><span class="eyebrow">El tiempo de crear es ahora</span><h2>Pequeñas ideas.<br>Grandes descubrimientos.</h2><p>Explora, prueba y aprende con TIME Codeman. Cada bloque es un paso más en tu aventura.</p><a class="primary" href="#jugar-1">¡A programar! →</a></div>${brandWidget()}</section>${authorCredit()}`;updateBrandClock()}
function renderGame(){const m=MISSIONS[current];$('#app').innerHTML=`<a class="back" href="#inicio">← Mi huerta</a><div class="play-heading"><div><span class="eyebrow">Misión 0${current+1} de 06 · ${m.skill}</span><h1>${m.title}</h1><p>${m.story}</p></div><label><span class="eyebrow">Ayuda </span><select class="mode" id="mode"><option value="guided">Exploradores · Más apoyo</option><option value="independent">Inventores · Menos apoyo</option></select></label></div><div class="play-layout"><section class="board-panel" aria-label="Recorrido de Semilla"><div class="board" id="board"></div><p class="legend">La flecha indica hacia dónde mira Semilla.</p></section><section class="editor" aria-label="Editor del programa"><div class="editor-top"><h3>Tu programa</h3><button class="link-button" id="clear">Borrar todo</button></div><div class="sequence" id="sequence" aria-label="Secuencia de instrucciones"></div><small id="edit-help">Toca un bloque de tu programa para quitarlo.</small><div class="blocks">${m.commands.map(c=>`<button class="block" data-add="${c}" aria-label="Añadir ${labels[c]}">${symbols[c]}<span>${labels[c]}</span></button>`).join('')}</div><div class="run-controls"><button class="primary" id="run">▶ Probar</button><button class="subtle" id="reset" aria-label="Volver al inicio conservando los bloques">↺ Inicio</button></div><div class="feedback" id="feedback" role="status" aria-live="polite">${current===4?'El programa tiene un giro equivocado. Pruébalo y observa.':'¡Tu turno! Semilla empieza mirando hacia arriba.'}</div><div class="play-bottom"><button class="subtle" id="hint">☀ Una pista</button><small id="count"></small></div><div id="hint-text"></div></section></div>`;$('#mode').value=mode;$('#mode').onchange=e=>{mode=e.target.value;$('#hint-text').innerHTML='';draw()};$('#clear').onclick=()=>{reset();program=[];lastSuccess=false;draw();message('¡Una nueva idea! Toca los bloques para construirla.')};$('#reset').onclick=()=>{reset();message('Semilla está al inicio. Conservamos tus bloques para que puedas revisarlos.')};$('#run').onclick=run;$('#hint').onclick=()=>{const text=mode==='guided'?m.hint:'Imagina el recorrido antes de probar. ¿Hacia dónde mira Semilla en cada esquina?';$('#hint-text').innerHTML=`<div class="hint">${text}</div>`;say(text)};$('#sequence').onclick=e=>{const b=e.target.closest('[data-index]');if(b&&!running){program.splice(Number(b.dataset.index),1);lastSuccess=false;errorIndex=-1;draw()}};document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(running)return;if(program.length>=24){message('Hay 24 bloques. Quita alguno para seguir construyendo.');return}program.push(b.dataset.add);lastSuccess=false;errorIndex=-1;draw();say(labels[b.dataset.add])});draw()}
function draw(active=-1){const m=MISSIONS[current];$('#board').innerHTML=Array.from({length:25},(_,i)=>{const x=i%5,y=Math.floor(i/5),path=m.path.some(p=>p[0]===x&&p[1]===y),bot=pos[0]===x&&pos[1]===y,goal=m.goal[0]===x&&m.goal[1]===y;return `<div class="cell ${path?'path':''} ${goal?'goal':''}" aria-label="Fila ${y+1}, columna ${x+1}: ${bot?'Semilla mirando '+['arriba','derecha','abajo','izquierda'][direction]:goal?'meta':path?'camino':'césped'}">${bot?`<span class="bot-token">🤖<b>${directions[direction]}</b></span>`:goal?m.plant:path?'':'🌿'}</div>`}).join('');$('#sequence').innerHTML=program.map((c,i)=>`<button class="command ${i===active?'active':''} ${i===errorIndex?'error':''}" data-index="${i}" aria-label="Quitar paso ${i+1}: ${labels[c]}" ${running?'disabled':''}>${symbols[c]}<small>${i+1}</small></button>`).join('');$('#count').textContent=`${program.length} / 24 bloques`;document.querySelectorAll('[data-add],#clear,#run,#mode').forEach(b=>b.disabled=running)}
function message(t){$('#feedback').textContent=t;say(t)}
function reset(){stop();pos=[...MISSIONS[current].start];direction=0;lastSuccess=false;errorIndex=-1;draw()}
function run(){if(!program.length){message('Primero toca Avanzar para añadir un bloque.');return}reset();running=true;attempts++;draw();step(0)}
function step(i){const m=MISSIONS[current];if(i>=program.length){running=false;draw();message('El programa terminó. ¡Falta un poquito! Añade bloques o cambia alguno.');return}const c=program[i];if(c==='F'){const d=[[0,-1],[1,0],[0,1],[-1,0]][direction],next=[pos[0]+d[0],pos[1]+d[1]];if(!m.path.some(p=>p[0]===next[0]&&p[1]===next[1])){running=false;errorIndex=i;draw();message(`En el paso ${i+1}, Semilla salió del camino. Revisa el bloque marcado y la dirección de la flecha.`);return}pos=next}else direction=(direction+(c==='L'?3:1))%4;draw(i);$('#feedback').textContent=`Paso ${i+1}: ${labels[c]}.`;if(pos[0]===m.goal[0]&&pos[1]===m.goal[1]){running=false;lastSuccess=true;const unused=program.length-i-1;saved[current]={complete:true,program:[...program],attempts,used:i+1};persist();draw(i);message('¡Lo lograste! Tu idea hizo crecer la huerta.');timer=setTimeout(()=>showResult(unused),450);return}timer=setTimeout(()=>step(i+1),mode==='guided'?800:550)}
function showResult(unused){const m=MISSIONS[current];const wrap=document.createElement('div');wrap.className='overlay';wrap.innerHTML=`<section class="result" role="dialog" aria-modal="true" aria-labelledby="result-title" tabindex="-1"><div class="reward">${m.plant}</div><span class="eyebrow">Una idea que florece</span><h2 id="result-title">¡Ganaste!</h2><div class="concept-card"><span class="eyebrow">💡 ¿Sabías que…?</span><div lang="en"><small>ENGLISH</small><h3>${m.concept.en.title}</h3><p>${m.concept.en.definition}</p><p class="concept-example">${m.concept.en.example}</p></div><div lang="es" class="concept-spanish"><small>ESPAÑOL</small><h3>${m.concept.title}</h3><p>${m.concept.definition}</p><p class="concept-example">${m.concept.example}</p></div><div class="concept-audio"><button class="subtle" id="read-concept">🔊 Inglés → Español</button><button class="subtle" id="stop-concept">■ Detener</button></div><p id="speech-status" role="status" aria-live="polite">Escucha el concepto en los dos idiomas.</p></div><p>${unused?`Llegaste a la planta. Quedaron ${unused} bloques sin usar: si quieres, vuelve y simplifica tu programa.`:'Tu secuencia llevó a Semilla hasta la planta.'}</p><p>¿Qué bloque fue importante para llegar?</p><a class="primary" href="${current<5?'#jugar-'+(current+2):'#inicio'}">${current<5?'Siguiente misión →':'Ver mi huerta 🌱'}</a><button class="subtle" id="retry">Revisar mi programa</button><a class="link-button" href="#inicio">Mi huerta</a></section>`;document.body.append(wrap);$('#read-concept').onclick=readConcept;$('#stop-concept').onclick=()=>{if('speechSynthesis'in window)speechSynthesis.cancel();$('#speech-status').textContent='Lectura detenida.'};$('#retry').onclick=()=>{if('speechSynthesis'in window)speechSynthesis.cancel();wrap.remove();$('#run').focus()};wrap.querySelector('.result').focus();if(voice)readConcept();wrap.onkeydown=e=>{if(e.key==='Escape'){$('#retry').click();return}if(e.key==='Tab'){const items=[...wrap.querySelectorAll('a,button')],first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===wrap.querySelector('.result'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}}
const teacherTabs={plan:'Plan de clase',support:'Acompañamiento',evaluation:'Evaluación',design:'Diseño y wireframes'};
function renderTeacher(){ $('#app').innerHTML=`<a class="back" href="#inicio">← Volver al juego</a><section class="teacher-intro"><span class="eyebrow">Para profes · Actividad 1</span><h1>Jugar con un propósito.</h1><p>Introducción al pensamiento algorítmico mediante programación visual por bloques. Propuesta de sesión de 35–40 minutos.</p><p class="teacher-author"><strong>Autoría: TIME Codeman</strong> · Código con propósito · @timecodeman</p></section><div class="tabs" role="tablist" aria-label="Material docente">${Object.entries(teacherTabs).map(([k,v])=>`<button role="tab" id="tab-${k}" aria-controls="teacher-content" data-tab="${k}" aria-selected="${tab===k}">${v}</button>`).join('')}</div><section id="teacher-content" role="tabpanel" aria-labelledby="tab-${tab}"></section><button class="subtle no-print" id="print">Imprimir esta sección</button>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderTeacher();$(`#tab-${tab}`).focus()});$('#print').onclick=()=>window.print();renderTeacherContent()}
const card=(title,body)=>`<article class="content-card"><h3>${title}</h3>${body}</article>`;
function renderTeacherContent(){let html='';if(tab==='plan')html=`<div class="teacher-grid">${card('Tema y pertinencia','<p>Secuencias de instrucciones, orientación y corrección de errores. El movimiento visible del robot permite relacionar cada instrucción con un efecto observable. La huerta aporta una historia cercana; el aprendizaje central es construir algoritmos.</p>')}${card('Público y contexto','<p>Niños de 5–10 años, en contextos rurales o urbanos, con celular, tableta o computador. Se propone trabajo individual o en parejas. El nivel de ayuda se ajusta al desempeño, con lectura acompañada cuando se necesite. Antes de la clase, verificar acceso y funcionamiento en los dispositivos.</p>')}${card('Problema de aprendizaje','<p>Se plantea como hipótesis la dificultad para ordenar pasos, anticipar el efecto de los giros y revisar una secuencia. Antes de afirmar una necesidad real del grupo, el docente debe recoger evidencia: pedir tres instrucciones para llegar a un objeto y observar su ejecución.</p>')}${card('Resultado de aprendizaje (1)','<p>Al finalizar, el estudiante construirá, ejecutará y ajustará una secuencia de instrucciones visuales que conduzca al robot hasta una meta, y explicará una decisión del recorrido con palabras, gestos o señalamiento.</p>')}</div>${card('Evidencia (1)','<p>Registro de una misión: secuencia de bloques y explicación de una decisión o corrección. El docente recoge la explicación y valora el proceso con la rúbrica; la aplicación por sí sola no comprueba comprensión.</p>')}${card('Secuencia didáctica','<ul><li><strong>Exploración · 8 min:</strong> diagnóstico oral y misiones 1–2 para descubrir el avance y anticipar movimientos.</li><li><strong>Aprendizaje · 10 min:</strong> modelar avance y giro con las misiones 3–4. Preguntar qué cambia cuando el robot gira.</li><li><strong>Práctica · 17–22 min:</strong> elegir misiones según el desempeño, corregir la misión 5 y combinar movimientos en la 6. Alternar roles y recoger la explicación. No es obligatorio completar las seis.</li></ul>')}`;
if(tab==='support')html=card('Dos formas de acompañar','<p><strong>Exploradores:</strong> más tiempo entre movimientos y pistas concretas. Recomendado como punto de partida con niños de 5–7 años o quienes necesiten apoyo.</p><p><strong>Inventores:</strong> menos apoyo explícito y preguntas de anticipación. Puede servir a niños de 8–10 años con mayor autonomía. Las misiones son las mismas; cambia el apoyo, no se impone una ruta por edad.</p>')+card('Preguntas que ayudan','<ul><li>¿Hacia dónde mira Semilla ahora?</li><li>¿Girar cambia su lugar o su dirección?</li><li>¿Qué crees que ocurrirá con el siguiente bloque?</li><li>¿En qué paso sucedió algo diferente a lo esperado?</li><li>¿Qué cambiaste y qué efecto tuvo?</li></ul>')+card('Inclusión y trabajo en parejas','<p>Sin cronómetro ni pérdida de vidas. Se puede repetir cualquier misión. Los controles incluyen iconos y texto; la voz es opcional y depende del navegador. En parejas, alternar quien programa y quien anticipa el resultado. Ofrecer una cuadrícula física cuando sea necesario.</p>');
if(tab==='evaluation')html=card('Evaluación formativa y seguimiento','<p>Observar cómo el estudiante anticipa, prueba y corrige. La retroalimentación señala el paso donde el robot salió del camino. Los intentos no restan puntos. Completar la meta no equivale por sí solo a alcanzar el resultado de aprendizaje.</p><p>El progreso y las últimas soluciones completadas se guardan en este navegador. No hay cuentas, sincronización ni panel de grupo. En dispositivos compartidos, estos datos representan el trabajo del dispositivo.</p><button class="primary no-print" id="export">↓ Descargar registro</button>')+card('Rúbrica de observación','<div class="table-wrap"><table><thead><tr><th>Criterio</th><th>Con apoyo</th><th>En proceso</th><th>Logrado</th></tr></thead><tbody><tr><th>Orden de instrucciones</th><td>Construye con modelado.</td><td>Ordena parte del recorrido y ajusta con pistas.</td><td>Construye una secuencia que lleva a la meta.</td></tr><tr><th>Prueba y corrección</th><td>Necesita ayuda para observar el efecto.</td><td>Reconoce un error con preguntas.</td><td>Identifica y modifica instrucciones según lo observado.</td></tr><tr><th>Explicación</th><td>Señala movimientos con ayuda.</td><td>Explica parcialmente una decisión.</td><td>Explica o representa una decisión y su efecto.</td></tr></tbody></table></div>');
if(tab==='design'){const wires=[['Inicio','Semilla y su huerta','🤖 🌱','¡Vamos a jugar!','Inicio → Misión o mapa'],['Mapa','Elige tu aventura','🌱 🌻 🌷','Explorar misión','Mapa → Juego'],['Juego','Llega hasta la planta','▦ 🤖 🌱','↑ ↶ ↷ · Probar','Juego → Ejecución'],['Corrección','Revisa el paso marcado','↑ ↑ ↶','Cambiar y probar','Corrección → Juego'],['Logro','¡Lo lograste!','🌻','Siguiente misión','Resultado → Misión o huerta'],['Profes','Jugar con un propósito','▤','Plan · Evaluación · Diseño','Profes → Material docente']];html=authorCredit()+card('Arquitectura de la experiencia','<p>Inicio y mapa comparten pantalla. El juego presenta una misión a la vez; la corrección es un estado del tablero y el logro es un diálogo. El espacio docente tiene navegación propia. Estos wireframes describen la versión implementada.</p>')+`<div class="wires">${wires.map((w,i)=>`<article class="wire"><small>0${i+1} · ${w[0]}</small><h3>${w[1]}</h3><div class="wire-art">${w[2]}</div><div class="wire-action">${w[3]}</div><p>${w[4]}</p></article>`).join('')}</div>`+card('Alcance y entrega académica','<p>Prototipo web con seis misiones de secuencias y giros. No incluye bucles, sensores ni evaluación automática de la explicación. La copia sin conexión requiere una primera visita completa mediante HTTPS o localhost; debe comprobarse en el equipo de uso.</p><p>La entrega académica todavía requiere contrastar la fundamentación con los materiales del curso, incorporar citas y referencias verificadas en APA 7 y contextualizar el problema con evidencia del grupo. No se inventan referencias ni diagnósticos.</p>')+card('Transparencia sobre el apoyo de IA','<p>Se utilizó ChatGPT/Codex (OpenAI) como apoyo para revisar la experiencia, redactar una propuesta y desarrollar el prototipo. El estudiante debe revisar, adaptar y explicar las decisiones pedagógicas, comprobar el funcionamiento y declarar este apoyo según las indicaciones del curso.</p>')}
$('#teacher-content').innerHTML=html;if($('#export'))$('#export').onclick=exportRecord}
function exportRecord(){let text='ROBOT SEMILLA — REGISTRO DEL DISPOSITIVO\nAutoría: TIME Codeman · @timecodeman\nNo identifica estudiantes. Completar mediante observación docente.\n\n';MISSIONS.forEach((m,i)=>{const s=saved[i];text+=`Misión ${i+1}: ${m.title}\nEstado: ${s?.complete?'Completada':'Sin registro'}\n`;if(s){text+=`Último programa completado: ${s.program.map(c=>labels[c]).join(' → ')}\nBloques ejecutados hasta la meta: ${s.used}\nIntentos en esa visita: ${s.attempts}\n`}text+='Explicación del estudiante: ____________________\nOrden / Prueba y corrección / Explicación: ____________________\n\n'});const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='robot-semilla-registro.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#voice').onclick=()=>{if(!('speechSynthesis'in window)){$('#voice').textContent='Voz no disponible';return}voice=!voice;$('#voice').setAttribute('aria-pressed',String(voice));$('#voice').textContent=voice?'Voz activa':'Voz';if(voice)say('Hola, soy Semilla. ¡Cultivemos ideas!');else speechSynthesis.cancel()};window.addEventListener('hashchange',route);route();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
